#!/bin/bash
# Build the 5 simulators used in this project and copy them to bin/.
#
# Usage: scripts/build_all.sh
# Needs GCC 7.5 as the default g++ (the Berti artifact's ChampSim does not
# build reliably with newer GCC).
#
# Each simulator is the same ChampSim with a different L1D prefetcher:
#   bin/champsim_nopf       no prefetcher
#   bin/champsim_ipstride   IP-stride
#   bin/champsim_bop        BOP (ours, from the HPCA'16 paper)
#   bin/champsim_berti      Berti (authors' code)
#   bin/champsim_bertigap   Berti + gap measurement (generated by make_berti_gap.py)

set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
SIM="$ROOT/Berti-Artifact/ChampSim/Berti"

# Regenerate berti_gap from Berti so the two never drift apart.
python3 "$ROOT/scripts/make_berti_gap.py"

mkdir -p "$ROOT/bin"
cd "$SIM"

# name in bin/  :  L1D prefetcher file (prefetcher/<name>.l1d_pref)
for pair in nopf:no ipstride:ip_stride bop:bop berti:vberti bertigap:berti_gap; do
    name=${pair%%:*}
    pf=${pair##*:}
    echo "== building champsim_$name (L1D prefetcher: $pf)"
    # Same settings as the Berti paper: hashed perceptron branch predictor,
    # no prefetching at other levels, LRU/SRRIP/DRRIP replacement, 1 core.
    ./build_champsim.sh hashed_perceptron no "$pf" no no no no no \
        lru lru lru srrip drrip lru lru lru 1 no > "$ROOT/bin/build_$name.log" 2>&1 \
        || { echo "build failed, see bin/build_$name.log"; exit 1; }
    cp "bin/hashed_perceptron-no-$pf-no-no-no-no-no-lru-lru-lru-srrip-drrip-lru-lru-lru-1core-no" \
        "$ROOT/bin/champsim_$name"
done

echo "built: $(ls "$ROOT/bin" | grep -v '\.log$' | tr '\n' ' ')"
